1import { useRef, useEffect } from "react";
2
3function Header({ query, onQueryChange }) {
4  const searchRef = useRef(null);
5
6  useEffect(function () {
7    searchRef.current.focus();
8  }, []);
9
10  function handleChange(e) {
11    onQueryChange(e.target.value);
12  }
13
14  function handleClear() {
15    onQueryChange("");
16    searchRef.current.focus();
17  }
18
19  return (
20    <header className="header">
21      <h2 className="title-primary">My Daily Journal</h2>
22      <p className="subtitle">Capture your thoughts, one day at a time.</p>
23      <div className="header-search">
24        <input
25          ref={searchRef}
26          className="search-input"
27          type="text"
28          placeholder="Search entries..."
29          value={query}
30          onChange={handleChange}
31        />
32        {query && (
33          <button className="btn-clear" onClick={handleClear}>Clear</button>
34        )}
35      </div>
36    </header>
37  );
38}
39
40export default Header;

1import { useRef, useEffect } from "react";
2
3function Drawer({ entry, onClose }) {
4  const drawerRef = useRef(null);
5
6  useEffect(function () {
7    function handleMouseDown(event) {
8      if (drawerRef.current && !drawerRef.current.contains(event.target)) {
9        onClose();
10      }
11    }
12
13    document.addEventListener("mousedown", handleMouseDown);
14    return function () {
15      document.removeEventListener("mousedown", handleMouseDown);
16    };
17  }, [onClose]);
18
19  if (!entry) return null;
20
21  return (
22    <div className="drawer-overlay">
23      <div className="drawer" ref={drawerRef}>
24        <button className="drawer-close" onClick={onClose}>×</button>
25        <h2>{entry.title}</h2>
26        <p className="drawer-meta">{entry.date} · {entry.author}</p>
27        <p className="drawer-content">{entry.content}</p>
28      </div>
29    </div>
30  );
31}
32
33export default Drawer;
